const raw = $input.first().json || {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const question = String(body.question || '').trim();
if (!question) return [{ json: { error: 'missing question' } }];
const domain = String(body.domain || 'career');
const facts = body.facts && typeof body.facts === 'object' ? body.facts : {};
let timeMode = String(body.timeMode || facts.timeMode || 'exact');
if (body.timeUnknown === true || facts.timeUnknown === true) timeMode = 'unknown';

const domainGuide = {
  career: '事业/合作：看长期适配与当下推进条件，给条件，不替用户拍板。',
  wealth: '财富/投入：看现金流、风险承受与投入产出，不做投资建议。',
  relationship: '亲密/关系：看边界、沟通与承诺，不预测分手、结婚或具体对象。',
  travel: '迁移/出行：看环境变化、外部机会与落脚点，不保证结果。',
  timing: '时机：回答该动还是该等，给出触发条件与止损点。'
}[domain] || '把长期结构与当下这件事分开说。';

const readingGuide = facts.readingGuide || (timeMode === 'unknown'
  ? '出生时辰不详。facts 里没有紫微命宫，禁止编造命宫、主星、四化、大限或时辰盘。这一问以奇门断事为主；全文最后温和询问是否愿意做「三问定盘」。'
  : timeMode === 'fuzzy'
    ? '只知道一个模糊时段。ziwei.variants 是每个时辰各排一次的摘要。只采用交集；矛盾就说清楚，不要挑一个时辰当成出生时辰。'
    : '时辰已定。紫微看长期结构，奇门看当下这件事。两盘不一致时分开说。');

const ziweiSystem = timeMode === 'unknown'
  ? '你是紫微斗数专家。出生时辰不详，facts 中没有可用紫微命盘。你只回复一句：「时辰不详，长期结构无法读取，不作紫微判断。」不要写任何星曜、宫位、四化或大限。'
  : '你是紫微斗数专家，只负责长期结构。只使用 facts.ziwei；不得新增星曜、宫位、四化、大限。只输出 3-5 条观察，每条不超过 40 字；不给最终建议，不写成散文。若是模糊时辰，只采用 variants 的共同点，矛盾要写明。';

const qimenSystem = '你是奇门遁甲专家，只负责当下时空。只使用 facts.qimen；不得新增门、星、神、宫位、局数。只输出 3-5 条观察，每条不超过 40 字；不给最终建议，不写成散文。';

const ziweiUser = [
  '问题：' + question,
  '领域：' + domainGuide,
  '时辰状态：' + timeMode,
  '紫微 facts：',
  JSON.stringify(facts.ziwei || {}, null, 2)
].join('\n');

const qimenUser = [
  '问题：' + question,
  '领域：' + domainGuide,
  '起局时间：' + (facts.qimen && facts.qimen.castAt || ''),
  '奇门 facts：',
  JSON.stringify(facts.qimen || {}, null, 2)
].join('\n');

return [{ json: {
  question, domain, timeMode, facts, readingGuide, domainGuide,
  ziweiMessages: [
    { role: 'system', content: ziweiSystem },
    { role: 'user', content: ziweiUser }
  ],
  qimenMessages: [
    { role: 'system', content: qimenSystem },
    { role: 'user', content: qimenUser }
  ]
} }];

const prep = $('Prepare').first().json;
const data = $input.first().json || {};
const content = data?.choices?.[0]?.message?.content || '';
return [{ json: { ...prep, ziweiExpert: content } }];

const data = $input.first().json || {};
const content = data?.choices?.[0]?.message?.content || '';
if (!content) return [{ json: { error: 'empty completion' } }];
return [{ json: { content, model: data.model || 'glm-4-plus' } }];
